// Resolve the caller's uid from X-User-Token (HMAC v1 token). No/invalid
// token -> uid null -> single-tenant fallback (company 1) via the SQL.
const crypto = require('crypto');
const req = $input.first().json || {};
const headers = req.headers || {};
const token = String(headers['x-user-token'] || headers['X-User-Token'] || '').trim();
const secret = $env.AUTH_TOKEN_SECRET || '';
let uid = null;
if (token && secret) {
  try {
    const parts = token.split('.');
    if (parts.length === 3 && parts[0] === 'v1') {
      const payloadB64 = parts[1];
      const expected = crypto.createHmac('sha256', secret).update(payloadB64).digest('base64url');
      const a = Buffer.from(parts[2]); const b = Buffer.from(expected);
      if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
        const payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString());
        if (payload.uid && payload.exp * 1000 > Date.now()) uid = payload.uid;
      }
    }
  } catch (e) { uid = null; }
}
return [{ json: { uid } }];

// POST to Vapi /chat with the resolved company variableValues; keep
// multi-turn context through previousChatId (client-supplied chatId).
const https = require('https');
const bodyIn = ($('Chat Webhook').first().json || {}).body || {};
const input = typeof bodyIn.input === 'string' ? bodyIn.input.trim() : '';
const chatId = typeof bodyIn.chatId === 'string' ? bodyIn.chatId.trim() : '';
const apiKey = $env.VAPI_PRIVATE_KEY || '';
const assistantId = $env.VAPI_ASSISTANT_ID || '67e2850c-1028-484d-bf52-d948826b2a7e';
if (!input) return [{ json: { ok: false, statusCode: 400, error: 'CHAT_MISSING_INPUT: body.input is required' } }];
if (!apiKey) return [{ json: { ok: false, statusCode: 500, error: 'CHAT_KEY_NOT_CONFIGURED' } }];

const ctx = $input.first().json;
const steps = !!ctx.setup_complete ? '' : [
  '# First-Run Setup (Onboarding) - follow these steps',
  '- Run onboarding BEFORE any other work when setup is incomplete.',
  '  1. Company name. 2. PM full name. 3. Preferred daily name.',
  '  4. Company billing address. 5. GST number (can be added later).',
  '  6. PST applicable + number (optional). 7. Payment instructions.',
  '  8. Each worker: name, trade, hourly rate (ask "anyone else?").',
  '  9. Then call complete_onboarding with all fields, and confirm.',
  '- Never call complete_onboarding before company name, PM name, preferred',
  '  address, and workers are gathered (empty workers array allowed).',
].join('\n');

const vapiBody = {
  assistantId,
  input,
  assistantOverrides: {
    variableValues: {
      setup_complete: !!ctx.setup_complete,
      company_name: ctx.company_name || '',
      pm_preferred_name: ctx.pm_preferred_name || '',
      onboarding_steps: steps,
    },
  },
};
if (chatId) vapiBody.previousChatId = chatId;

function post(u, headers, body) {
  return new Promise((resolve, reject) => {
    const m = u.match(/^https?:\/\/([^/]+)(\/[^?#]*)?/);
    const req = https.request({
      method: 'POST', hostname: m[1], path: (m[2] || '/'),
      headers,
    }, (res) => {
      let data = ''; res.on('data', (c) => (data += c));
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject); req.write(body); req.end();
  });
}

return (async () => {
  try {
    const resp = await post('https://api.vapi.ai/chat', {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + apiKey,
    }, JSON.stringify(vapiBody));
    if (resp.status !== 200 && resp.status !== 201) {
      return [{ json: { ok: false, statusCode: 502, error: 'VAPI_CHAT_ERROR ' + resp.status + ': ' + resp.body.slice(0, 300) } }];
    }
    const data = JSON.parse(resp.body);
    // reply = last assistant text across output messages
    const out = Array.isArray(data.output) ? data.output : [];
    // final reply = LAST assistant message that carries text (skips any
    // intermediate 'just a sec' filler and tool-call frames)
    let reply = '';
    for (let i = out.length - 1; i >= 0; i--) {
      const msg = out[i];
      if (!msg || msg.role !== 'assistant') continue;
      const c = msg.content;
      let t = '';
      if (typeof c === 'string') t = c;
      else if (Array.isArray(c)) {
        for (const p of c) if (p && typeof p.text === 'string') t += p.text;
      }
      if (t.trim()) { reply = t.trim(); break; }
    }
    return [{ json: { ok: true, chatId: String(data.id || ''), reply, cost: data.cost } }];
  } catch (e) {
    return [{ json: { ok: false, statusCode: 502, error: 'CHAT_NETWORK_ERROR: ' + e.message } }];
  }
})();
